    if (entries.every(([, v]) => typeof v === "string")) {
      fieldErrors = Object.fromEntries(entries) as Record<string, string>;
    }
  }
  return fieldErrors
    ? { code: e.code, message: e.message, fieldErrors }
    : { code: e.code, message: e.message };
