import { expect, it, vi } from "vitest";
import { http, HttpResponse } from "msw";
import { server } from "../mocks/node.ts";
import { activateScenario, resolveScenario } from "../mocks/scenarios.ts";
import { getSessions, getSessionDetails, createSession } from "../shared/api/client.ts";
import { localToIsoUtc } from "../shared/lib/datetime.ts";
it("scenario order", () => {
  const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
  expect(resolveScenario("?scenario=empty", "list-error")).toEqual({ name: "empty", source: "url" });
  expect(resolveScenario("", "list-error")).toEqual({ name: "list-error", source: "env" });
  expect(resolveScenario("?scenario=bad", "list-error")).toEqual({ name: "list-error", source: "env" });
  expect(resolveScenario("?scenario=bad", "bad2")).toEqual({ name: "normal", source: "default" });
  expect(resolveScenario("", undefined)).toEqual({ name: "normal", source: "default" });
  expect(warn).toHaveBeenCalledTimes(3);
});
it("api behaviour", async () => {
  server.use(...activateScenario("list-error"));
  const r = await getSessions();
  expect(r.ok === false && !r.cancelled && r.error.kind === "api" && r.error.code).toBe("SESSIONS_UNAVAILABLE");
  server.resetHandlers(); 
  server.use(http.get("/api/sessions", () => new HttpResponse("<html>", { headers: { "content-type": "text/html" } })));
  const h = await getSessions(); expect(h.ok === false && !h.cancelled && h.error.kind).toBe("malformed");
  server.use(http.get("/api/sessions", () => HttpResponse.error()));
  const n = await getSessions(); expect(n.ok === false && !n.cancelled && n.error.kind).toBe("network");
  const ac = new AbortController(); const p = getSessionDetails("ses_101", { signal: ac.signal }); ac.abort();
  expect(await p).toEqual({ ok: false, cancelled: true });
  const e = activateScenario("empty"); expect(e).toEqual([]);
  const l = await getSessions(); expect(l.ok && l.data.data.length).toBe(0);
  const c = await createSession({ title: "x", type: "camp", startsAt: "2026-09-01T10:00:00.000Z", durationMinutes: 30, coachId: "coach_02", locationName: "a", locationAddress: "b", capacity: 3, visibility: "invite-only", description: " " });
  expect(c.ok && c.data.id).toBe("ses_101");
  const bad = await createSession({ title: "", type: "camp", startsAt: "x", durationMinutes: 0, coachId: "zz", locationName: "", locationAddress: "", capacity: 3, visibility: "public" });
  expect(bad.ok === false && !bad.cancelled && bad.error.kind === "api" && Object.keys(bad.error.fieldErrors ?? {}).length).toBeGreaterThan(3);
  expect((await getSessions({ query: " x " })).ok).toBe(true);
  expect(localToIsoUtc("2026-02-30", "10:00")).toEqual({ ok: false, reason: "invalid-date" });
});
EOF
